function overlay(ctx, title, lines, hint) {
  ctx.fillStyle = 'rgba(43,29,18,0.72)';
  ctx.fillRect(0, 0, W, H);
  ctx.fillStyle = '#fff8e7';
  rr(ctx, 180, 120, 600, 330, 16); ctx.fill();
